contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept an input amount and a dummy address to exercise external call paths.
    function run(uint amount, address /*unused*/) public payable {
        require(amount == c.TICKET_AMOUNT());
        // ensure this contract has enough balance to forward the ticket amount
        require(address(this).balance >= amount);

        // read pot before the call
        uint potBefore = c.pot();
        uint balanceBefore = address(c).balance;

        // perform the state-changing call; capture whether it reverted
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint potAfter = c.pot();
        uint balanceAfter = address(c).balance;

        // General invariant: contract's on-chain Ether balance equals its public pot value
        // after the attempted play call (regardless of revert or branch taken).
        assert(balanceAfter == potAfter);
    }

    // allow receiving refunds when the contract is paid out
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept inputs for ticket payment amount and an extra bool to optionally pre-fund pot by calling play once.
    function run(uint amount, bool prefund) public payable {
        require(address(this).balance >= amount);
        // read constants/observables before interactions
        address bankBefore = c.bank();
        uint potBefore = c.pot();
        uint balThisBefore = address(this).balance;
        uint balCBefore = address(c).balance;

        // optionally pre-fund by calling play once with exact ticket amount to change pot state
        if (prefund) {
            // only call if we have enough balance and amount equals ticket size
            if (amount == C(address(c)).TICKET_AMOUNT()) {
                // top-level state-changing call
                bool reverted;
                try c.play{value: amount}() {
                    reverted = false;
                } catch {
                    reverted = true;
                }
                // if it reverted then nothing changed aside from gas; ensure bank unchanged
                if (reverted) {
                    assert(c.bank() == bankBefore);
                }
            }
            // refresh observed values after optional prefund
            potBefore = c.pot();
            balThisBefore = address(this).balance;
            balCBefore = address(c).balance;
        }

        // Now perform the main call with the provided amount. Must have balance.
        require(address(this).balance >= amount);

        bool revertedMain;
        try c.play{value: amount}() {
            revertedMain = false;
        } catch {
            revertedMain = true;
        }

        // read after-values
        uint potAfter = c.pot();
        uint balThisAfter = address(this).balance;
        uint balCAfter = address(c).balance;
        address bankAfter = c.bank();

        // General rule (single assert): if call reverted, pot and balances unchanged and bank unchanged; otherwise either payout branch occurred (pot becomes 0 and contract balance decreased by at least FEE_AMOUNT and caller net increased by potBefore + amount - FEE_AMOUNT) or no-payout branch occurred (pot increases by exactly amount and caller balance decreased by exactly amount). We express this succinctly:
        uint T = C(address(c)).TICKET_AMOUNT();
        uint F = C(address(c)).FEE_AMOUNT();

        assert(
            // bank never changes
            bankAfter == bankBefore
            && (
                // if reverted: nothing changed except gas (we require pot and balances equal)
                (revertedMain && potAfter == potBefore && balThisAfter == balThisBefore && balCAfter == balCBefore)
                ||
                // else not reverted: either payout happened -> pot becomes 0 and c balance decreased by (potBefore + amount) and caller gained that minus fee
                (!revertedMain && (
                    // valid call must have been made with exact ticket amount
                    amount == T
                    && (
                        // payout branch: pot resets to 0 and contract balance decreased by (potBefore + amount) and caller increased accordingly (taking into account fee)
                        (potAfter == 0 && balCAfter + (potBefore + amount) == balCBefore && balThisAfter + F + balCAfter == balThisBefore + balCBefore)
                        ||
                        // no-payout branch: pot increased by exactly amount and caller paid exactly amount
                        (potAfter == potBefore + amount && balThisAfter + amount == balThisBefore && balCAfter == balCBefore + amount)
                    )
                ))
            )
        );
    }

    receive() external payable { }
}

