contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We need to receive Ether when c.transfer sends funds back to this contract
    receive() external payable {}

    // single public test function
    function run(uint sendAmount) public payable {
        // Precondition: ensure this contract has enough balance to send sendAmount
        require(address(this).balance >= sendAmount);

        // Read observable before-values
        address bankBefore = c.bank();
        uint potBefore = c.pot();
        uint balThisBefore = address(this).balance;
        uint balCBefore = address(c).balance;

        bool reverted;
        // Call play with provided amount (must be passed as value)
        try c.play{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        address bankAfter = c.bank();
        uint potAfter = c.pot();
        uint balThisAfter = address(this).balance;
        uint balCAfter = address(c).balance;

        // The general rule asserted:
        // If the call reverted then state must be unchanged (bank and pot and balances equal before)
        // If the call did not revert and sendAmount == TICKET_AMOUNT then bank is unchanged, and either
        //   (A) pot increased by sendAmount (no payout happened), or
        //   (B) pot is zero and this contract's balance increased by at least potBefore + sendAmount - c.FEE_AMOUNT() (winner got pot minus fee)
        // We express fee constant via observing balances: in payout case, c's balance decreases by (potBefore + sendAmount) and this contract's balance increases accordingly, except feeAmount goes to bank.

        // Build the logical condition
        bool ok;
        if (reverted) {
            ok = (bankAfter == bankBefore) && (potAfter == potBefore) && (balThisAfter == balThisBefore) && (balCAfter == balCBefore);
        } else {
            // call succeeded
            // bank should never change
            bool bankUnchanged = (bankAfter == bankBefore);

            // Case A: pot increased by sendAmount
            bool caseA = (potAfter == potBefore + sendAmount) && (balCAfter == balCBefore + sendAmount) && (balThisAfter == balThisBefore);

            // Case B: pot reset to zero and balances reflect payout of (potBefore + sendAmount) less fee to caller
            // fee is FEE_AMOUNT constant in C, but not directly accessible: infer from balance changes between c and bank/this.
            // In payout, potAfter == 0 and c balance decreased by (potBefore + sendAmount) and this contract received (potBefore + sendAmount - ?). The bank should have received FEE_AMOUNT.
            bool potReset = (potAfter == 0);
            bool cBalanceDropped = (balCAfter + (potBefore + sendAmount) == balCBefore);
            // This contract must have gained at least (potBefore + sendAmount) - (balCBefore - balCAfter) equals the amount sent from c to others; but simpler: this contract's balance non-decreased except for the outgoing sendAmount
            // More precise: this contract initially sent sendAmount, then if it won it should get back potBefore + sendAmount - FEE_AMOUNT. So final balance >= balThisBefore - sendAmount + (potBefore + sendAmount) - (balCBefore - balCAfter - (potBefore + sendAmount) /*should be zero*/) simplifies to balThisAfter >= balThisBefore + potBefore - FEE_AMOUNT
            // We cannot read FEE_AMOUNT, so instead assert that balThisAfter >= balThisBefore - sendAmount + (potBefore + sendAmount) - (balCBefore - balCAfter - 0);
            // Use observable: the sum of balances of c plus this plus bank should be preserved (ignoring gas). But bank balance not observable. So we'll assert that in reset case, this contract's balance increased by at least potBefore (i.e., it recovered the pot except possibly a small fee), which is a weaker but general property.
            bool thisGainedAtLeastPotBefore = (balThisAfter >= balThisBefore - sendAmount + potBefore);

            bool caseB = potReset && cBalanceDropped && thisGainedAtLeastPotBefore;

            ok = bankUnchanged && (caseA || caseB || (sendAmount != c.TICKET_AMOUNT()));
            // include sendAmount != TICKET_AMOUNT: if caller sent wrong value, play() should revert, but if it didn't revert (unexpected), we allow the condition to be vacuously true only if one of the cases holds; keep defensiveness
        }

        assert(ok);
    }
}

