    // accept refunds/winnings from C
    receive() external payable {}

    // single public test function: take sendAmount as input and attempt to call play
    function run(uint sendAmount) public payable {
        // must be able to fund the attempted payment
        require(address(this).balance >= sendAmount);

        // observe before-values
        address bankBefore = c.bank();
        uint potBefore = c.pot();

        bool reverted;
        // call play with the supplied amount
        try c.play{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-values
        address bankAfter = c.bank();
        uint potAfter = c.pot();

        // If the caller provided exactly the ticket amount, the call must not revert
        // and afterwards the bank must be unchanged, and pot is either increased by the ticket amount or reset to 0.
        // For other sendAmount values the call may revert; in that case we only require bank unchanged and pot unchanged.

        uint T = c.TICKET_AMOUNT();

        if (sendAmount == T) {
            // when the correct ticket payment is sent, call should not revert
            // and bank unchanged, and potAfter is either potBefore + T or 0
            assert(reverted == false);
            assert(bankAfter == bankBefore);
            assert(potAfter == potBefore + T || potAfter == 0);
        } else {
            // when incorrect amount sent, either it reverted and left observable state unchanged,
            // or (unexpectedly) it succeeded but must still preserve bank and follow the same pot-change pattern
