            || (!reverted && (
                (afterPot == 0 && (afterC + afterThis) + 1 == (beforeC + beforeThis))
                || (afterPot == beforePot + amount && (afterC + afterThis) == (beforeC + beforeThis))
            ))
        );
    }
}
